// ── Pots the randomizer never shuffles ───────────────────────────────────────
// sramLocations.ts lists every pot in the game, including the ones sitting on
// switches (and a few blocks) that pot shuffle leaves alone — the game never
// sets their bit, so counting them left rooms stuck one short forever (Eastern
// Lobby showing 3 pots when only 2 are locations). The reference region logic
// is the pool that actually gets shuffled, so anything it has no entry for is
// dropped here, keyed by "offset:mask" so the room's own name can't matter.
// Regenerate from logic_regions.ts if the reference data changes.
(function (window) {
  var EXCLUDED = ["19:32", "21:32", "63:128", "77:32", "87:64", "127:8", "149:128", "149:1", "157:32", "174:128", "183:64", "191:128", "201:2", "231:32", "233:64", "253:32", "281:128", "295:128", "319:16", "341:8", "349:128", "359:32", "363:32", "369:128", "377:16", "381:128", "389:128", "403:32", "437:32"];
  var skip = {};
  EXCLUDED.forEach(function (k) { skip[k] = 1; });
  var L = window.POT_LOCATIONS || {};
  Object.keys(L).forEach(function (r) {
    var e = L[r];
    if (!e.pots) return;
    e.pots = e.pots.filter(function (p) { return !skip[p[0] + ':' + p[1]]; });
    if (!e.pots.length) delete e.pots;
  });
})(window);
